mapper.select:
		/*deleteMasterCmClPurchaseTaxsheetIssueReg_ICOMGRDT*/
		SELECT LOGIS_TAX_BILL_NO 
         FROM ICOMGRDT 
         WHERE AP_TAX_BILL_NO = #{TAX_BILL_NO}
            AND LOGIS_BILL_FLAG = 'Y'

		/*deleteMasterCmClPurchaseTaxsheetIssueReg_ICOMIVDT_v2*/
		SELECT LOGIS_TAX_BILL_NO 
         FROM ICOMIVDT 
         WHERE AP_TAX_BILL_NO = #{TAX_BILL_NO}
            AND LOGIS_BILL_FLAG = 'Y'

/*selectMasterCmClPurchaseTaxsheetIssueRegList*/
SELECT SB.KEP_IRS_NAME ,SB.SITE_GUBUN_NAME ,SB.IRS_NO ,REPLACE(SB.IRS_NO,'-','') AS REPLACE_AGENT_IRS_NO ,SB.AGENT_CODE ,SB.CUSTOMER_NAME ,NVL(SB.BILL_CODE, CASE WHEN MAIN.CONVERSATION_ID IS NULL THEN ( SELECT CMPY.BILL_CODE FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = SB.AGENT_CODE ) WHEN MAIN.CONVERSATION_ID IS NOT NULL THEN '41000008' ELSE '90000001' END ) AS BILL_CODE_TEXT , NVL(TO_CHAR(MAIN.DTI_WDATE,'YYYYMMDD'), SB.ISSUE_DATE ) AS ISSUE_DATE ,SB.SUPP_PRICE ,SB.TAX_PRICE ,SB.AMT ,SB.TAX_TYPE_TEXT ,SB.BILL_TYPE_TEXT ,SB.TAX_BILL_NO ,SB.CONFIRM_FLAG ,SB.STATUS ,SB.CHANGE_DATE ,SB.SEND_DATE ,SB.REMARK_DESCRIPTION ,SB.KEP_IRS_NO ,SB.SITE_GUBUN_CODE ,SB.DEPT_CODE ,SB.TAX_TYPE ,SB.TOT_TAX_PRICE ,SB.CLOSE_MONTH ,SB.AP_CLOSE_REVISION ,SB.COM_NAME_LOC_ORDER ,SB.NTS_SEND_FLAG ,SB.IF_SEND_FLAG ,SB.ADD_USER_ID ,SB.INDUSTRY_TYPE ,SB.BUSINESS_ITEMS ,SB.ADDRESS_LOC ,SB.CEO_NAME_LOC ,REPLACE(IRS.IRS_NO,'-','') AS KEP_COM_IRS_NO ,IRS.IRS_NAME AS KEP_COM_NAME_LOC ,IRS.BUSINESS_ITEMS AS KEP_COM_BUSINESS_ITEMS ,IRS.INDUSTRY_TYPE AS KEP_COM_INDUSTRY_TYPE ,IRS.CEO_NAME_LOC AS KEP_COM_CEO_NAME_LOC ,IRS.ADDRESS_LOC AS KEP_COM_ADDRESS_LOC ,USR.FND_USER_NAME AS KEP_USER_NAME ,USR.EMAIL AS KEP_USER_EMAIL ,USR.SMART_ID AS SMART_ID ,USR.SMART_PASSWORD AS SMART_PASSWORD ,USR.AUTHTOKEN AS AUTHTOKEN ,NVL(MAIN.SUP_EMAIL, NVL(SB.EMAIL, BILL.EMAIL)) AS RECV_EMAIL ,NVL(MAIN.SUP_EMP_NAME, NVL(SB.EMAIL_NAME, BILL.USER_NAME_LOC)) AS RECV_USER_NAME ,BILL.PHONE_NUMBER AS RECV_PHONE_NUMBER ,MAIN.AMEND_CODE AS AMEND_CODE ,MAIN.CONVERSATION_ID AS CONVERSATION_ID ,MAIN.ISSUE_ID AS ISSUE_ID ,MAIN.ORI_ISSUE_ID AS ORI_ISSUE_ID ,STATUS.DTI_STATUS AS DTI_STATUS ,(SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE='TX11' AND CODE=STATUS.DTI_STATUS) AS DTI_STATUS_TEXT ,STATUS.RETURN_DESCRIPTION AS RETURN_DESCRIPTION ,STATUS.NTS_SEND_STATUS ,STATUS.NTS_RESULT_CODE ,STATUS.RETURN_CODE STATUS_RETURN_CODE ,#{st_user_id} AS CREATED_BY ,MAIN.CREATED_BY AS MAIN_CREATED_BY ,NVL(DECODE(LENGTH(SB.ASK_TYPE),1,'0'||SB.ASK_TYPE,SB.ASK_TYPE),'02') AS AR_REQ_TYPE ,SB.APDT_REMARK ,SB.SUP_BIZPLACE_CODE ,MAIN.SUP_AMOUNT AS MAIN_SUP_AMOUNT ,MAIN.TAX_AMOUNT AS MAIN_TAX_AMOUNT ,MAIN.TOTAL_AMOUNT AS MAIN_TOTAL_AMOUNT ,DECODE(MAIN.CONVERSATION_ID,'',DECODE(SB.EMAIL,'','N','Y'),'N') AS AP_MAIL_SEND_YN ,DECODE(MAIN.CONVERSATION_ID,'','',DECODE(STATUS.DTI_STATUS,'V','[역발행메일재전송]','I','[역발행메일재전송]','')) AS AP_R_MAIL_SEND ,DECODE(MAIN.CONVERSATION_ID,'','N',DECODE(SB.EMAIL,'','N','Y')) AS AP_R_MAIL_SEND_YN ,DECODE(MAIN.CONVERSATION_ID,'','',SB.EMAIL) AS AP_R_MAIL_SEND_MAIL ,(SELECT DECODE(COUNT(*), 0, 'N', 'Y') FROM ICOMCOD3 WHERE BUYER = 'KRKORE0001' AND TYPE = 'SMTX' AND CODE1 = (SELECT MAX(BUYER_CODE) FROM KEPTAPDT WHERE TAX_BILL_NO = SB.TAX_BILL_NO AND DEPT_CODE = SB.DEPT_CODE) AND CODE2 = SB.AGENT_CODE) AS ICOMCOD3_SMTX_YN FROM( SELECT MAX((SELECT TEXT4 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = APDT.SITE)) AS KEP_IRS_NAME , MAX((SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = APDT.SITE)) AS SITE_GUBUN_NAME, MAX(IRS_NO) AS IRS_NO, MAX(SITE) AS SITE, MAX(APDT.AGENT_CODE) AS AGENT_CODE, MAX(CUSTOMER_NAME) AS CUSTOMER_NAME, MAX(ISSUE_DATE) AS ISSUE_DATE, SUM(APDT.SUPP_PRICE) AS SUPP_PRICE, SUM(APDT.TAX_PRICE) AS TAX_PRICE, MAX(TOT_AMT) AS AMT, MAX(APDT.TAX_TYPE) AS TAX_TYPE_TEXT, MAX(APDT.BILL_TYPE) AS BILL_TYPE_TEXT, MAX(APDT.TAX_BILL_NO) AS TAX_BILL_NO, MAX(APDT.CONFIRM_FLAG) AS CONFIRM_FLAG, MAX(DECODE(IF_SEND_FLAG,NULL,'미전송','N','전송중','E','전송오류','Y','전송완료')) AS STATUS, MAX(APDT.CHANGE_DATE) AS CHANGE_DATE, MAX(APDT.SEND_DATE) AS SEND_DATE, MAX((SELECT REMARK_DESCRIPTION FROM KEPTITEM WHERE TAX_BILL_NO = APDT.TAX_BILL_NO AND ITEM_SEQ = '000001')) REMARK_DESCRIPTION, MAX(APDT.KEP_IRS) AS KEP_IRS_NO, MAX(APDT.SITE) AS SITE_GUBUN_CODE, MAX(APDT.DEPT_CODE) AS DEPT_CODE, MAX(APDT.TAX_TYPE) AS TAX_TYPE, MAX(APDT.TOT_TAX_PRICE) AS TOT_TAX_PRICE, MAX(APDT.AP_CLOSE_MONTH) AS CLOSE_MONTH, MAX(APDT.AP_CLOSE_REVISION) AS AP_CLOSE_REVISION, MAX(TRIM(REPLACE(REPLACE(REPLACE(REPLACE(CUSTOMER_NAME,'(유)',''),'(사)',''),'(주)',''),'㈜',''))) AS COM_NAME_LOC_ORDER, MAX(NTS_SEND_FLAG) AS NTS_SEND_FLAG, MAX(DECODE(IF_SEND_FLAG,NULL,'N','N','N','E','E','Y','Y')) AS IF_SEND_FLAG, MAX(APDT.ADD_USER_ID) AS ADD_USER_ID, MAX(APDT.INDUSTRY_TYPE) AS INDUSTRY_TYPE, MAX(APDT.BUSINESS_ITEMS) AS BUSINESS_ITEMS, MAX(APDT.ADDRESS_LOC) AS ADDRESS_LOC, MAX(APDT.CEO_NAME_LOC) AS CEO_NAME_LOC, MAX(APDT.ASK_TYPE) AS ASK_TYPE, MAX(APDT.REMARK) AS APDT_REMARK, MAX(APDT.SUP_BIZPLACE_CODE) AS SUP_BIZPLACE_CODE, MAX(APDT.BILL_CODE) AS BILL_CODE, MAX(APDT.EMAIL_NAME) AS EMAIL_NAME, MAX(APDT.EMAIL) AS EMAIL FROM KEPTAPDT APDT /* 외상매입_세금계산서 */ WHERE APDT.ISSUE_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND APDT.SITE = 'KA' AND APDT.STATUS <> 'D'
AND APDT.BUYER_CODE = #{st_buyer_code}
AND APDT.IRS_NO LIKE '%'||#{st_agent_irs_no} || '%'
AND APDT.AGENT_CODE = #{st_agent_code}
AND APDT.ADD_USER_ID = #{st_add_user_id}
AND APDT.BILL_TYPE = #{st_bill_type}
AND APDT.DEPT_CODE = #{st_user_dept}
AND DECODE(IF_SEND_FLAG,NULL,'미전송','N','전송중','E','전송오류','Y','전송완료') = #{st_send_flag}
AND APDT.BILL_TYPE = #{st_bill_type_text}
AND (SELECT BILL_CODE FROM ICOMCMPY WHERE COM_CODE = APDT.AGENT_CODE) = #{st_bill_code_text}
AND APDT.TAX_BILL_NO LIKE #{st_tax_bill_no}||'%'
AND APDT.CONFIRM_FLAG = #{st_confirm_flag}
GROUP BY APDT.TAX_BILL_NO ) SB, KEPTIRSN IRS, XXSB_DTI_SM_USER USR, XXSB_DTI_MAIN MAIN, XXSB_DTI_STATUS STATUS, BILL_ACCOUNTING BILL WHERE SB.KEP_IRS_NO = IRS.IRS_NO AND SB.SITE = IRS.SITE AND IRS.COM_CODE = 'KRKORE0001' AND REPLACE(SB.KEP_IRS_NO,'-','') = USR.FND_REGNO(+) AND USR.FND_USER (+)= #{st_user_id} AND SB.TAX_BILL_NO = MAIN.SEQ_ID(+) AND MAIN.CONVERSATION_ID = STATUS.CONVERSATION_ID(+) AND SB.AGENT_CODE = BILL.COM_CODE (+) AND SB.IRS_NO = BILL.IRS_NO (+)
AND STATUS.DTI_STATUS = #{st_dti_status}
AND STATUS.NTS_SEND_STATUS = #{st_ntd_sendstatus}
AND MAIN.CONVERSATION_ID IS NULL
AND BILL.PRIORITY (+)= 'Y' AND MAIN.STATUS (+)!= 'D' ORDER BY COM_NAME_LOC_ORDER, SB.TAX_BILL_NO ,MAIN.CONVERSATION_ID, NVL(TO_CHAR(MAIN.DTI_WDATE,'YYYYMMDD'), SB.ISSUE_DATE )

/*selectMasterCmClPurchaseTaxsheetIssueRegList_Detail*/
SELECT SB.KEP_IRS_NAME ,SB.SITE_GUBUN_NAME ,SB.IRS_NO ,SB.CUSTOMER_NAME ,SB.AGENT_CODE ,SB.CUSTOMER_NAME , NVL(TO_CHAR(MAIN.DTI_WDATE,'YYYYMMDD'), SB.ISSUE_DATE ) AS ISSUE_DATE ,SB.TOT_SUPP_PRICE ,SB.TOT_TAX_PRICE ,SB.TOT_AMT ,SB.DEPT_NAME ,SB.SUPP_PRICE ,SB.TAX_PRICE ,SB.AMT ,SB.TAX_TYPE ,SB.BILL_TYPE ,SB.TAX_BILL_NO ,SB.STATUS AS STATUS_NM ,SB.CHANGE_DATE ,SB.SEND_DATE ,SB.REMARK_DESCRIPTION ,SB.KEP_IRS ,SB.SITE_GUBUN_CODE ,SB.DEPT_CODE ,STATUS.DTI_STATUS ,(SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE='TX11' AND CODE=STATUS.DTI_STATUS) AS DTI_STATUS_TEXT FROM( SELECT (SELECT TEXT4 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NAME , (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = APDT.SITE) AS SITE_GUBUN_NAME , IRS_NO AS IRS_NO , CUSTOMER_NAME AS CUSTOMER_NAME , ISSUE_DATE AS ISSUE_DATE , TOT_SUPP_PRICE AS TOT_SUPP_PRICE , TOT_TAX_PRICE AS TOT_TAX_PRICE , TOT_AMT AS TOT_AMT , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE ='TX06' AND CODE = APDT.DEPT_CODE) DEPT_NAME , APDT.SUPP_PRICE , APDT.TAX_PRICE , APDT.AMT , (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE ='TX02' AND CODE = APDT.TAX_TYPE) TAX_TYPE , (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE ='TX03' AND CODE = APDT.BILL_TYPE) BILL_TYPE , APDT.TAX_BILL_NO AS TAX_BILL_NO , DECODE(IF_SEND_FLAG, NULL, '미전송', 'N', '전송대기', 'E', '전송오류', 'Y', '전송완료', 'W', '취소대기', 'F', '취소오류', 'C', '취소완료') AS STATUS , APDT.CHANGE_DATE AS CHANGE_DATE , APDT.SEND_DATE AS SEND_DATE , APDT.REMARK_DESCRIPTION AS REMARK_DESCRIPTION , APDT.KEP_IRS AS KEP_IRS , APDT.SITE AS SITE_GUBUN_CODE , APDT.DEPT_CODE AS DEPT_CODE , APDT.AGENT_CODE , APDT.KEP_IRS AS KEP_IRS_NO , APDT.SITE FROM KEPTAPDT APDT /* 외상매입_세금계산서 */ WHERE 1=1 AND STATUS <> 'D' AND APDT.ISSUE_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND APDT.SITE = 'KA'
AND APDT.BUYER_CODE = #{st_buyer_code}
AND APDT.IRS_NO LIKE '%'||#{st_agent_irs_no} || '%'
AND APDT.AGENT_CODE = #{st_agent_code}
AND APDT.ADD_USER_ID = #{st_add_user_id}
AND APDT.BILL_TYPE = #{st_bill_type}
AND APDT.DEPT_CODE = #{st_user_dept}
AND DECODE(IF_SEND_FLAG,NULL,'미전송','N','전송중','E','전송오류','Y','전송완료') = #{st_send_flag}
AND APDT.BILL_TYPE = #{st_bill_type_text}
AND (SELECT BILL_CODE FROM ICOMCMPY WHERE COM_CODE = APDT.AGENT_CODE) = #{st_bill_code_text}
AND APDT.TAX_BILL_NO LIKE #{st_tax_bill_no}||'%'
) SB, KEPTIRSN IRS, XXSB_DTI_SM_USER USR, XXSB_DTI_MAIN MAIN, XXSB_DTI_STATUS STATUS, BILL_ACCOUNTING BILL WHERE SB.KEP_IRS_NO = IRS.IRS_NO AND SB.SITE = IRS.SITE AND IRS.COM_CODE = 'KRKORE0001' AND REPLACE(SB.KEP_IRS_NO,'-','') = USR.FND_REGNO(+) AND USR.FND_USER (+)= #{st_user_id} AND SB.TAX_BILL_NO = MAIN.SEQ_ID(+) AND MAIN.CONVERSATION_ID = STATUS.CONVERSATION_ID(+) AND SB.AGENT_CODE = BILL.COM_CODE (+) AND SB.IRS_NO = BILL.IRS_NO (+)
AND STATUS.DTI_STATUS = #{st_dti_status}
AND STATUS.NTS_SEND_STATUS = #{st_ntd_sendstatus}
AND MAIN.CONVERSATION_ID IS NULL
AND BILL.PRIORITY (+)= 'Y' AND MAIN.STATUS (+)!= 'D' ORDER BY SB.CUSTOMER_NAME, SB.TAX_BILL_NO ,MAIN.CONVERSATION_ID, NVL(TO_CHAR(MAIN.DTI_WDATE,'YYYYMMDD'), SB.ISSUE_DATE )

mapper.update:
/*updateMasterCmClPurchaseTaxsheetIssueReg*/

		UPDATE 
		    KEPTAPDT /* 외상매입_세금계산서 */
		SET 
		    CHANGE_USER_ID  = #{st_user_id}
		  , CHANGE_DATE     = TO_CHAR(SYSDATE, 'YYYYMMDD')
		  , CHANGE_TIME     = TO_CHAR(SYSDATE, 'HH24MISS')
		  , ISSUE_DATE      = #{ISSUE_DATE}
		  , TAX_TYPE        = #{TAX_TYPE_TEXT}
		  , BILL_TYPE       = #{BILL_TYPE_TEXT}
		  , ASK_TYPE       =  #{AR_REQ_TYPE}
		  , REMARK       = #{APDT_REMARK}
		  , SUP_BIZPLACE_CODE = #{SUP_BIZPLACE_CODE}
		  , BILL_CODE = #{BILL_CODE_TEXT}
		WHERE 
		    TAX_BILL_NO     = #{TAX_BILL_NO}

/*updateMasterCmClPurchaseTaxsheetIssueReg_Pay*/

		UPDATE 
		    KEPTAPDT /* 외상매입_세금계산서 */
		SET 
		    PAY_TERMS    = #{PAY_TERMS}
		WHERE 
		    TAX_BILL_NO  = #{TAX_BILL_NO}

/*deleteMasterCmClPurchaseTaxsheetIssueReg*/

		UPDATE KEPTAPDT /* 외상매입_세금계산서 */
		SET STATUS = 'D' 
		WHERE 
		    TAX_BILL_NO = #{TAX_BILL_NO}

/*delApMasterCmClPurchaseTaxsheetIssueRegList*/

		UPDATE XXSB_DTI_MAIN
		SET STATUS = 'D' 
		, LAST_UPDATE_DATE = SYSDATE
		, LAST_UPDATED_BY = #{st_user_id}
		WHERE   CONVERSATION_ID = #{CONVERSATION_ID}

/*updateMasterCmClPurchaseTaxsheetIssueReg_BillCloseList*/

		UPDATE
		    BILL_CLOSE_USER_LIST
		SET 
		    CLOSE_CMPL_YN = 'N'
		WHERE 1=1
		AND LEGACY_USER_ID = (SELECT LEGACY_USER_ID FROM ICOMLUSR WHERE USER_ID = #{st_user_id})
		AND BILL_CLOSE_MONTH = #{CLOSE_MONTH}
		AND CLOSE_TYPE = 'AP' 
		AND AGENT_CODE = #{AGENT_CODE}

/* sendApMailMasterCmClPurchaseTaxsheetIssueReg1 */

		UPDATE 
		    KEPTAPDT /* 외상매입_세금계산서 */
		SET 
		    EMAIL_NAME = #{RECV_USER_NAME} || '(정)',
		    EMAIL = #{RECV_EMAIL}
		WHERE 
		    TAX_BILL_NO  = #{TAX_BILL_NO}

/* rsendApMailMasterCmClPurchaseTaxsheetIssueReg */

		UPDATE 
		    KEPTAPDT /* 외상매입_세금계산서 */
		SET 
		    EMAIL_NAME = #{RECV_USER_NAME} || '(역)',
		    EMAIL = #{RECV_EMAIL}
		WHERE 
		    TAX_BILL_NO  = #{TAX_BILL_NO}

/*updateMasterCmClApBillCloseUserList*/		 


UPDATE BILL_CLOSE_USER_LIST
SET CLOSE_CMPL_YN = 'Y'
WHERE LEGACY_USER_ID = (SELECT LEGACY_USER_ID FROM ICOMLUSR WHERE USER_ID = #{st_user_id})
AND BILL_CLOSE_MONTH = #{CLOSE_MONTH}
AND CLOSE_TYPE = #{close_type}

/*deleteMasterCmClApBillCloseUserList*/		 


DELETE FROM BILL_CLOSE_USER_LIST		
WHERE LEGACY_USER_ID = (SELECT LEGACY_USER_ID FROM ICOMLUSR WHERE USER_ID =#{st_user_id})
AND BILL_CLOSE_MONTH = #{CLOSE_MONTH}
AND CLOSE_TYPE = 'AP'
AND AGENT_CODE NOT IN (
		SELECT AGENT_CODE FROM KEPTAPDT
				WHERE STATUS <> 'D'
				AND   AP_CLOSE_MONTH = #{CLOSE_MONTH}						
				AND   ADD_USER_ID = #{st_user_id}
				GROUP BY AGENT_CODE
)

/*updateMasterCmClSalesTaxsheetIssueReg_ApConfirm*/

		UPDATE
		    KEPTAPDT
		SET 
		    CONFIRM_FLAG    = 'Y'
		  , CONFIRM_USER_ID = #{st_user_id}
		  , CONFIRM_DATE    = TO_CHAR(SYSDATE, 'YYYYMMDD')
		  , CONFIRM_TIME    = TO_CHAR(SYSDATE, 'HH24MISS')
		  , CHANGE_USER_ID  = #{st_user_id}
		  , CHANGE_DATE     = TO_CHAR(SYSDATE, 'YYYYMMDD')
		  , CHANGE_TIME     = TO_CHAR(SYSDATE, 'HH24MISS')
		WHERE 1=1
		AND ADD_USER_ID 	= #{st_user_id}
		AND AP_CLOSE_MONTH  = #{CLOSE_MONTH}
		AND CONFIRM_FLAG    = 'N'
